const baselineSource = "import { Capacitor } from '@capacitor/core'\nimport { App } from '@capacitor/app'\nimport {\n  APP_BACKGROUND_SUSPEND_EVENT,\n  APP_FOREGROUND_RECOVERY_EVENT,\n  APP_INTERACTIVE_MEDIA_RECOVERY_EVENT,\n} from '../utils/appForeground'\nimport {\n  cycleAccentLevel,\n  resolveUiTick,\n} from '../metronome/metronomeTiming'\nimport {\n  metronomeSpeakerGain,\n} from '../utils/playbackVolume'\nimport { primePlaybackAudioContextSync, resumePlaybackAudioContext } from '../utils/playbackAudioContext'\nimport BestTakeAudioPlugin from '../utils/audioSessionRoute'\nimport { isHeadphoneOutputActive } from '../utils/headphoneOutput'\nimport { engageStereoPlaybackAsync, releaseStereoPlayback } from '../utils/stereoPlaybackRoute'\nimport { scheduleMetronomeClick } from '../utils/metronomeClickSounds'\nimport {\n  isNativeIosMetronome,\n  nativeMetronomeAddBarListener,\n  nativeMetronomeAddPulseListener,\n  nativeMetronomeAddStateListener,\n  nativeMetronomePrepare,\n  nativeMetronomeIsPlaying,\n  nativeMetronomeSetMuted,\n  nativeMetronomeStart,\n  nativeMetronomeStop,\n  nativeMetronomeUpdate,\n} from '../utils/nativeMetronome'\nimport {\n  secondsPerSchedulerTick,\n  ticksPerBar,\n  ticksPerPulse,\n} from '../metronome/metronomeTiming'\nimport {\n  clampBpm,\n  getAccentLevelsForMeter,\n  getMeterDefaults,\n  hasFeelOptions,\n  loadMetronomePrefs,\n  normalizeAccentLevels,\n  resolveClickTierWithAccents,\n  saveMetronomePrefs,\n  suggestSubdivisionForMeterChange,\n  type MetronomeAccentLevel,\n  type MetronomeClickTier,\n  type MetronomeMeter,\n  type MetronomeSubdivision,\n} from '../utils/metronomeConfig'\nimport { resolvePulseTiming } from './pulseResolution'\nimport { meterHasPulseModeChoice } from './pulseModes'\n\nconst SCHEDULE_AHEAD_SEC = 0.12\nconst LOOKAHEAD_MS = 25\nconst START_LEAD_SEC = 0.05\nconst FOREGROUND_RECOVERY_DELAY_MS = 200\n\nexport interface SharedMetronomeSnapshot {\n  bpm: number\n  meter: MetronomeMeter\n  subdivision: MetronomeSubdivision\n  feelId?: string\n  pulseModeId: string\n  pulseCount: number\n  compound: boolean\n  bpmSymbol: string\n  pulseName: string\n  accentLevels: MetronomeAccentLevel[]\n  soundId: string\n  playing: boolean\n  beatIndex: number\n  subTickIndex: number\n  beatPulseId: number\n}\n\ntype Listener = () => void\ntype BarListener = () => void\ntype PulseListener = (beatIndex: number) => void\ntype TickListener = (event: {\n  beatIndex: number\n  subTickIndex: number\n  audible: boolean\n}) => void\n\nfunction createInitialSnapshot(): SharedMetronomeSnapshot {\n  const prefs = loadMetronomePrefs()\n  const defaults = getMeterDefaults(prefs.meter, prefs.pulseModeId)\n  const resolved = resolvePulseTiming({\n    meter: prefs.meter,\n    pulseModeId: defaults.pulseModeId,\n    feelId: prefs.feelId ?? defaults.feelId,\n    customAccents: prefs.accentLevels,\n  })\n  return {\n    bpm: prefs.bpm,\n    meter: prefs.meter,\n    subdivision: prefs.subdivision,\n    feelId: resolved.feelId,\n    pulseModeId: resolved.pulseModeId,\n    pulseCount: resolved.pulseCount,\n    compound: resolved.compound,\n    bpmSymbol: resolved.bpmSymbol,\n    pulseName: resolved.pulseName,\n    accentLevels: normalizeAccentLevels(\n      prefs.meter,\n      resolved.accentLevels,\n      resolved.feelId,\n      resolved.pulseModeId,\n    ),\n    soundId: prefs.soundId,\n    playing: false,\n    beatIndex: 0,\n    subTickIndex: 0,\n    beatPulseId: 0,\n  }\n}\n\nclass SharedMetronomeEngine {\n  private listeners = new Set<Listener>()\n  private barListeners = new Set<BarListener>()\n  private pulseListeners = new Set<PulseListener>()\n  private tickListeners = new Set<TickListener>()\n  private snapshot: SharedMetronomeSnapshot = createInitialSnapshot()\n\n  private audioCtx: AudioContext | null = null\n  private masterGain: GainNode | null = null\n  private schedulerTimer: number | null = null\n  private schedulerSession = 0\n  private nextBeatTime = 0\n  private tickCounter = 0\n\n  private isTakePlaying = false\n  private muteDuringPlayback = true\n  /**\n   * The click was running when a take started playing back. Hands-free listen-back\n   * reconfigures the audio session and the native engine reports stopped; that is\n   * not the player turning the metronome off. `resumeClickWanted` brings it back\n   * when the take is done, including a routine step that started the click for them.\n   */\n  private resumeClickWanted = false\n  private clickResumeUntil = 0\n  private clickResumeGeneration = 0\n  private outputGainMultiplier = 1\n  private resumeOnForeground = false\n  private lifecycleAttached = false\n  private isBackgrounded = false\n  private foregroundTimer: number | null = null\n  private recoveringForeground = false\n  /** Bumped per mode-switch recovery pass so overlapping passes cannot fight. */\n  private modeSwitchRecoveryGeneration = 0\n  private startInFlight = false\n  private controlGeneration = 0\n  private nativeControlQueue: Promise<void> = Promise.resolve()\n  private nativeRouteQueue: Promise<void> = Promise.resolve()\n  private nativeSpeakerRouteHeld = false\n  private nativeListenersAttached = false\n  private readonly useNativeAudio = isNativeIosMetronome()\n  private playbackWatchCtx: AudioContext | null = null\n  private onPlaybackStateChange: (() => void) | null = null\n  private webAudioResumeCtx: AudioContext | null = null\n  private webAudioResumeInFlight: Promise<void> | null = null\n  /**\n   * Exact time of the first click scheduled by the most recent start(), on both\n   * the Web Audio clock (for slaving media playback) and performance.now()\n   * (for stamping recording offsets). This is the multitrack timeline anchor.\n   */\n  private lastStartInfo: { firstClickCtxTime: number; firstClickPerfMs: number } | null = null\n\n  getLastStartInfo = (): { firstClickCtxTime: number; firstClickPerfMs: number } | null =>\n    this.lastStartInfo\n\n  subscribe = (listener: Listener): (() => void) => {\n    this.listeners.add(listener)\n    return () => {\n      this.listeners.delete(listener)\n    }\n  }\n\n  subscribeBar = (listener: BarListener): (() => void) => {\n    this.barListeners.add(listener)\n    return () => {\n      this.barListeners.delete(listener)\n    }\n  }\n\n  /** Fires at the start of each conducting pulse (subTick 0). beatIndex is 0-based. */\n  subscribePulse = (listener: PulseListener): (() => void) => {\n    this.pulseListeners.add(listener)\n    return () => {\n      this.pulseListeners.delete(listener)\n    }\n  }\n\n  /** Fires on each scheduled tick, including subdivisions. */\n  subscribeTick = (listener: TickListener): (() => void) => {\n    this.tickListeners.add(listener)\n    return () => {\n      this.tickListeners.delete(listener)\n    }\n  }\n\n  private emitBar(): void {\n    for (const listener of this.barListeners) {\n      listener()\n    }\n  }\n\n  private emitPulse(beatIndex: number): void {\n    for (const listener of this.pulseListeners) {\n      listener(beatIndex)\n    }\n  }\n\n  private emitTick(event: Parameters<TickListener>[0]): void {\n    for (const listener of this.tickListeners) {\n      listener(event)\n    }\n  }\n\n  private enqueueNativeControl<T>(operation: () => Promise<T>): Promise<T> {\n    const result = this.nativeControlQueue.then(operation, operation)\n    this.nativeControlQueue = result.then(\n      () => undefined,\n      () => undefined,\n    )\n    return result\n  }\n\n  private enqueueNativeRoute<T>(operation: () => Promise<T>): Promise<T> {\n    const result = this.nativeRouteQueue.then(operation, operation)\n    this.nativeRouteQueue = result.then(\n      () => undefined,\n      () => undefined,\n    )\n    return result\n  }\n\n  getSnapshot = (): SharedMetronomeSnapshot => this.snapshot\n\n  private emit(): void {\n    for (const listener of this.listeners) {\n      listener()\n    }\n  }\n\n  private patchState(partial: Partial<SharedMetronomeSnapshot>): void {\n    this.snapshot = { ...this.snapshot, ...partial }\n    this.emit()\n  }\n\n  private debugLog(message: string): void {\n    if (!import.meta.env.DEV) return\n    console.log(`[SharedMetronome] ${message}`)\n  }\n\n  private shouldMuteOutput(): boolean {\n    return this.muteDuringPlayback && this.isTakePlaying\n  }\n\n  private attachNativeListeners(): void {\n    if (!this.useNativeAudio || this.nativeListenersAttached) return\n    this.nativeListenersAttached = true\n\n    void nativeMetronomeAddStateListener(event => {\n      if (event.playing || !this.snapshot.playing || this.startInFlight) return\n      // A take owns the session. Remember that the click should return, and do\n      // not treat the engine dying as Stop \u2014 Stop is what cancels the return.\n      if (this.resumeClickWanted || Date.now() < this.clickResumeUntil) {\n        this.resumeClickWanted = true\n        this.patchState({ playing: false })\n        // Listen-back owns the session. A take that is still recording does not.\n        if (this.isTakePlaying) void this.releaseNativeSpeakerRoute()\n        if (!this.isTakePlaying && Date.now() < this.clickResumeUntil) this.queueClickResume()\n        return\n      }\n      this.stop()\n    })\n\n    void nativeMetronomeAddPulseListener((event) => {\n      if (!this.snapshot.playing) return\n      this.emitTick({\n        beatIndex: event.beatIndex,\n        subTickIndex: event.subTickIndex,\n        audible: event.audible !== false,\n      })\n      if (event.subTickIndex === 0) {\n        this.emitPulse(event.beatIndex)\n      }\n      this.patchState({\n        beatIndex: event.beatIndex,\n        subTickIndex: event.subTickIndex,\n        beatPulseId: event.beatPulseId,\n      })\n      this.debugLog(`beat=${event.beatIndex + 1} subTick=${event.subTickIndex}`)\n    })\n\n    void nativeMetronomeAddBarListener(() => {\n      if (this.snapshot.playing) {\n        this.emitBar()\n      }\n    })\n  }\n\n  private buildNativeTierPattern(): Array<MetronomeClickTier | null> {\n    const { meter, subdivision, accentLevels, pulseCount } = this.snapshot\n    const barTicks = ticksPerBar(meter, subdivision, pulseCount)\n    const pattern: Array<MetronomeClickTier | null> = []\n    for (let tick = 0; tick < barTicks; tick += 1) {\n      pattern.push(\n        resolveClickTierWithAccents(meter, tick, subdivision, accentLevels, pulseCount),\n      )\n    }\n    return pattern\n  }\n\n  private buildNativeTimingPayload(): {\n    tierPattern: Array<MetronomeClickTier | null>\n    ticksPerBar: number\n    pulseTicks: number\n    secondsPerTick: number\n    soundId: string\n  } {\n    const { meter, subdivision, bpm, pulseCount, soundId } = this.snapshot\n    return {\n      tierPattern: this.buildNativeTierPattern(),\n      ticksPerBar: ticksPerBar(meter, subdivision, pulseCount),\n      pulseTicks: ticksPerPulse(meter, subdivision, pulseCount),\n      secondsPerTick: secondsPerSchedulerTick(meter, bpm, subdivision, pulseCount),\n      soundId,\n    }\n  }\n\n  private pushNativeTimingUpdate(): void {\n    if (!this.useNativeAudio || !this.snapshot.playing) return\n    void nativeMetronomeUpdate(this.buildNativeTimingPayload())\n  }\n\n  private async ensurePlaybackRouteForMetronome(): Promise<void> {\n    if (!Capacitor.isNativePlatform()) return\n    try {\n      const { isPlaybackRouteHoldActive, preparePlaybackRoute } = await import(\n        '../utils/playbackRouteCoordinator'\n      )\n      if (!isPlaybackRouteHoldActive()) {\n        await preparePlaybackRoute({ suspendCamera: false })\n      }\n    } catch {\n      /* mic capture may block briefly \u2014 stereo route still helps */\n    }\n  }\n\n  private ensureNativeSpeakerRoute(): Promise<void> {\n    return this.enqueueNativeRoute(() => this.ensureNativeSpeakerRouteUnlocked())\n  }\n\n  private async ensureNativeSpeakerRouteUnlocked(): Promise<void> {\n    if (!Capacitor.isNativePlatform()) return\n\n    if (this.useNativeAudio && isHeadphoneOutputActive()) {\n      if (!this.nativeSpeakerRouteHeld) {\n        this.nativeSpeakerRouteHeld = true\n        await this.ensurePlaybackRouteForMetronome()\n      }\n      try {\n        await nativeMetronomePrepare()\n      } catch {\n        /* native prepare is a no-op on external output */\n      }\n      return\n    }\n\n    if (!this.nativeSpeakerRouteHeld) {\n      await this.ensurePlaybackRouteForMetronome()\n      await engageStereoPlaybackAsync()\n      this.nativeSpeakerRouteHeld = true\n    }\n    try {\n      const { reassertPlaybackRouteForCountIn } = await import('../utils/playbackRouteCoordinator')\n      await reassertPlaybackRouteForCountIn()\n    } catch {\n      /* camera session may block briefly \u2014 stereo route still helps */\n    }\n  }\n\n  private releaseNativeSpeakerRoute(): Promise<void> {\n    return this.enqueueNativeRoute(() => this.releaseNativeSpeakerRouteUnlocked())\n  }\n\n  private async releaseNativeSpeakerRouteUnlocked(): Promise<void> {\n    if (!this.nativeSpeakerRouteHeld) return\n    this.nativeSpeakerRouteHeld = false\n    if (this.useNativeAudio && isHeadphoneOutputActive()) {\n      return\n    }\n    await releaseStereoPlayback()\n  }\n\n  /**\n   * Re-assert the playback route in place. This used to release first, which\n   * sent the session through the recording route (enableRecordingRoute) while\n   * the click was sounding, only to put the playback route straight back:\n   * two session reconfigurations, each of which stops the native engine.\n   * ensureNativeSpeakerRouteUnlocked already re-applies the loud/coexistent\n   * session when the hold is kept, which is all a surface change needs.\n   */\n  private reassertNativeSpeakerRoute(): Promise<void> {\n    return this.enqueueNativeRoute(async () => {\n      if (!this.snapshot.playing) return\n      await this.ensureNativeSpeakerRouteUnlocked()\n    })\n  }\n\n  private applyMasterGain(): void {\n    if (this.useNativeAudio) {\n      void nativeMetronomeSetMuted(this.shouldMuteOutput())\n      return\n    }\n    const ctx = this.audioCtx\n    const master = this.masterGain\n    if (!ctx || !master || master.context !== ctx) return\n    master.gain.setValueAtTime(\n      metronomeSpeakerGain(this.shouldMuteOutput()) * this.outputGainMultiplier,\n      ctx.currentTime,\n    )\n  }\n\n  /** Optional session gain (e.g. multitrack mixer). Resets to 1 when not used. */\n  setOutputGainMultiplier(multiplier: number): void {\n    this.outputGainMultiplier = Math.max(0, Math.min(1, multiplier))\n    this.applyMasterGain()\n  }\n\n  /**\n   * Call at the moment listen-back is requested, before the route change, so a\n   * native stop that arrives ahead of React still counts as \"the click was on\".\n   */\n  holdClickAcrossPlayback = (): void => {\n    this.clickResumeGeneration += 1\n    if (!this.snapshot.playing && !this.resumeClickWanted) return\n    if (this.snapshot.playing) this.resumeClickWanted = true\n  }\n\n  private finishTakePlaybackClickHold(): void {\n    const shouldResume = this.resumeClickWanted && !this.snapshot.playing\n    if (!shouldResume) {\n      if (this.snapshot.playing) this.resumeClickWanted = false\n      return\n    }\n    this.queueClickResume()\n  }\n\n  /** Bring a click back after listen-back once the playback route has let go. */\n  private queueClickResume(): void {\n    if (!this.resumeClickWanted) return\n    this.clickResumeGeneration += 1\n    const generation = this.clickResumeGeneration\n    this.clickResumeUntil = Date.now() + 4000\n    const attempt = (index: number) => {\n      if (generation !== this.clickResumeGeneration || !this.resumeClickWanted) return\n      if (this.isTakePlaying) return\n      if (this.snapshot.playing) {\n        this.resumeClickWanted = false\n        return\n      }\n      void this.start({ recovered: true, fromStale: true }).then(ok => {\n        if (generation !== this.clickResumeGeneration) return\n        if (ok && this.snapshot.playing) {\n          window.setTimeout(() => {\n            if (generation !== this.clickResumeGeneration) return\n            if (this.snapshot.playing && !this.isTakePlaying) this.resumeClickWanted = false\n          }, 400)\n          return\n        }\n        if (index < 5) window.setTimeout(() => attempt(index + 1), 350 * (index + 1))\n      })\n    }\n    window.setTimeout(() => attempt(0), 250)\n  }\n\n  setPlaybackMutePolicy(isTakePlaying: boolean, muteDuringPlayback: boolean): void {\n    const wasTakePlaying = this.isTakePlaying\n    if (!wasTakePlaying && isTakePlaying) this.holdClickAcrossPlayback()\n    this.isTakePlaying = isTakePlaying\n    this.muteDuringPlayback = muteDuringPlayback\n    this.applyMasterGain()\n    if (wasTakePlaying && !isTakePlaying) this.finishTakePlaybackClickHold()\n  }\n\n  attachLifecycle(): void {\n    if (this.lifecycleAttached || typeof window === 'undefined') return\n    this.lifecycleAttached = true\n    this.attachNativeListeners()\n\n    if (!this.useNativeAudio) {\n      this.attachPlaybackInterruptWatch()\n    }\n\n    const onBackground = () => {\n      if (this.isBackgrounded) return\n      this.isBackgrounded = true\n\n      if (this.foregroundTimer !== null) {\n        window.clearTimeout(this.foregroundTimer)\n        this.foregroundTimer = null\n      }\n\n      // Native sample-clock playback continues without WebKit timers. Keep the\n      // route and intent intact; ordinary browser tabs retain their old policy.\n      if (this.useNativeAudio) return\n\n      if (this.snapshot.playing) {\n        this.resumeOnForeground = true\n      }\n      this.hardStop({ background: true })\n    }\n\n    const onForeground = () => {\n      this.isBackgrounded = false\n      if (this.useNativeAudio) {\n        // Calls may have stopped native playback while JS was suspended. Read\n        // reality without restarting or resetting the downbeat on app return.\n        const generation = this.controlGeneration\n        void nativeMetronomeIsPlaying().then(playing => {\n          if (generation !== this.controlGeneration || this.isBackgrounded) return\n          if (this.snapshot.playing && playing === false) this.stop()\n        })\n        return\n      }\n      void resumePlaybackAudioContext().finally(() => {\n        this.reconcileAfterInterrupt()\n      })\n    }\n\n    const onVisibilityChange = () => {\n      if (document.visibilityState === 'hidden') {\n        onBackground()\n      } else {\n        onForeground()\n      }\n    }\n\n    const onPageHide = () => {\n      if (this.snapshot.playing || this.resumeOnForeground) {\n        onBackground()\n      }\n    }\n\n    document.addEventListener('visibilitychange', onVisibilityChange)\n    window.addEventListener('pageshow', onForeground)\n    window.addEventListener('focus', onForeground)\n    window.addEventListener('pagehide', onPageHide)\n    window.addEventListener(APP_BACKGROUND_SUSPEND_EVENT, onBackground)\n    window.addEventListener(APP_FOREGROUND_RECOVERY_EVENT, onForeground)\n    window.addEventListener(APP_INTERACTIVE_MEDIA_RECOVERY_EVENT, onForeground)\n\n    const retryOnUserGesture = () => {\n      if (!this.resumeOnForeground || this.snapshot.playing) return\n      this.reconcileAfterInterrupt()\n    }\n    document.addEventListener('pointerdown', retryOnUserGesture, { passive: true, capture: true })\n\n    if (Capacitor.isNativePlatform()) {\n      void App.addListener('appStateChange', ({ isActive }) => {\n        if (!isActive) {\n          onBackground()\n        } else {\n          onForeground()\n        }\n      })\n      void App.addListener('pause', onBackground)\n      void App.addListener('resume', onForeground)\n    }\n  }\n\n  private attachPlaybackInterruptWatch(): void {\n    const ctx = primePlaybackAudioContextSync()\n    if (this.playbackWatchCtx === ctx && this.onPlaybackStateChange) return\n\n    if (this.playbackWatchCtx && this.onPlaybackStateChange) {\n      this.playbackWatchCtx.removeEventListener('statechange', this.onPlaybackStateChange)\n    }\n\n    const onStateChange = () => {\n      if (ctx.state !== 'running' && this.snapshot.playing) {\n        this.requestWebAudioResume(ctx)\n        return\n      }\n      if (ctx.state === 'running' && this.resumeOnForeground) {\n        this.reconcileAfterInterrupt()\n      }\n    }\n\n    this.playbackWatchCtx = ctx\n    this.onPlaybackStateChange = onStateChange\n    ctx.addEventListener('statechange', onStateChange)\n  }\n\n  /** Avoid piling up WebKit resume promises while an interrupted context is stalled. */\n  private requestWebAudioResume(ctx: AudioContext): void {\n    if (ctx.state === 'running' || ctx.state === 'closed') return\n    if (this.webAudioResumeCtx === ctx && this.webAudioResumeInFlight) return\n\n    this.webAudioResumeCtx = ctx\n    const resumePromise = ctx.resume().catch(() => {})\n    this.webAudioResumeInFlight = resumePromise\n    void resumePromise.finally(() => {\n      if (this.webAudioResumeCtx !== ctx) return\n      this.webAudioResumeCtx = null\n      this.webAudioResumeInFlight = null\n    })\n  }\n\n  private reconcileAfterInterrupt(): void {\n    if (this.resumeOnForeground) {\n      this.scheduleForegroundRecovery()\n      return\n    }\n\n    if (!this.snapshot.playing) return\n    if (this.useNativeAudio) return\n\n    const ctx = this.audioCtx ?? primePlaybackAudioContextSync()\n    const audioNeedsRecovery = ctx.state !== 'running'\n    if (!this.isSchedulerHealthy() || audioNeedsRecovery) {\n      this.resumeOnForeground = true\n      this.scheduleForegroundRecovery()\n    }\n  }\n\n  private scheduleForegroundRecovery(): void {\n    if (this.foregroundTimer !== null) {\n      window.clearTimeout(this.foregroundTimer)\n    }\n    this.foregroundTimer = window.setTimeout(() => {\n      this.foregroundTimer = null\n      void this.handleForegroundRecovery()\n    }, FOREGROUND_RECOVERY_DELAY_MS)\n  }\n\n  private async handleForegroundRecovery(): Promise<void> {\n    if (!this.resumeOnForeground) {\n      this.isBackgrounded = false\n      if (this.snapshot.playing) {\n        this.patchState({ playing: false, beatIndex: 0, subTickIndex: 0 })\n      }\n      return\n    }\n\n    if (this.recoveringForeground) return\n    this.recoveringForeground = true\n    this.isBackgrounded = false\n\n    this.debugLog('foreground recovery')\n    this.clearSchedulerTimer()\n    this.releaseAudioGraph()\n\n    try {\n      if (!this.useNativeAudio) {\n        await resumePlaybackAudioContext()\n        this.attachPlaybackInterruptWatch()\n      }\n\n      for (let attempt = 0; attempt < 6; attempt++) {\n        if (!this.resumeOnForeground) return\n\n        if (attempt > 0) {\n          await new Promise((resolve) => window.setTimeout(resolve, 100 * attempt))\n          if (!this.useNativeAudio) {\n            await resumePlaybackAudioContext()\n          }\n        }\n\n        const started = await this.start({ recovered: true })\n        if (started) {\n          this.resumeOnForeground = false\n          this.debugLog('foreground recovery complete')\n          return\n        }\n      }\n\n      this.debugLog('foreground recovery failed; keeping resume intent')\n    } finally {\n      this.recoveringForeground = false\n    }\n  }\n\n  private enrichPulseFields(\n    partial: Partial<SharedMetronomeSnapshot>,\n  ): Partial<SharedMetronomeSnapshot> {\n    const meter = partial.meter ?? this.snapshot.meter\n    const pulseModeId = partial.pulseModeId ?? this.snapshot.pulseModeId\n    const feelId = partial.feelId !== undefined ? partial.feelId : this.snapshot.feelId\n    const accentLevels = partial.accentLevels ?? this.snapshot.accentLevels\n    const resolved = resolvePulseTiming({\n      meter,\n      pulseModeId,\n      feelId,\n      customAccents: accentLevels,\n    })\n    return {\n      pulseModeId: resolved.pulseModeId,\n      pulseCount: resolved.pulseCount,\n      compound: resolved.compound,\n      bpmSymbol: resolved.bpmSymbol,\n      pulseName: resolved.pulseName,\n      feelId: resolved.feelId,\n      accentLevels: normalizeAccentLevels(\n        meter,\n        resolved.accentLevels,\n        resolved.feelId,\n        resolved.pulseModeId,\n      ),\n    }\n  }\n\n  private persistPrefs(\n    nextBpm: number = this.snapshot.bpm,\n    nextMeter: MetronomeMeter = this.snapshot.meter,\n    nextSubdivision: MetronomeSubdivision = this.snapshot.subdivision,\n    nextFeelId: string | undefined = this.snapshot.feelId,\n    nextAccentLevels: MetronomeAccentLevel[] = this.snapshot.accentLevels,\n    nextSoundId: string = this.snapshot.soundId,\n    nextPulseModeId: string = this.snapshot.pulseModeId,\n  ): void {\n    saveMetronomePrefs({\n      bpm: nextBpm,\n      meter: nextMeter,\n      subdivision: nextSubdivision,\n      feelId: nextFeelId,\n      pulseModeId: nextPulseModeId,\n      accentLevels: normalizeAccentLevels(nextMeter, nextAccentLevels, nextFeelId, nextPulseModeId),\n      soundId: nextSoundId,\n    })\n  }\n\n  setBpm = (value: number): void => {\n    const next = clampBpm(value)\n    this.patchState({ bpm: next })\n    this.persistPrefs(next)\n    this.pushNativeTimingUpdate()\n  }\n\n  setMeter = (nextMeter: MetronomeMeter): void => {\n    const defaults = getMeterDefaults(nextMeter)\n    const nextSubdivision = suggestSubdivisionForMeterChange(\n      nextMeter,\n      this.snapshot.meter,\n      this.snapshot.subdivision,\n      defaults.pulseModeId,\n      this.snapshot.pulseModeId,\n    )\n    const nextFeelId = defaults.feelId\n    const nextAccentLevels = getAccentLevelsForMeter(nextMeter, nextFeelId, defaults.pulseModeId)\n    this.tickCounter = 0\n    this.patchState({\n      meter: nextMeter,\n      subdivision: nextSubdivision,\n      feelId: nextFeelId,\n      pulseModeId: defaults.pulseModeId,\n      beatIndex: 0,\n      subTickIndex: 0,\n      accentLevels: nextAccentLevels,\n      ...this.enrichPulseFields({\n        meter: nextMeter,\n        pulseModeId: defaults.pulseModeId,\n        feelId: nextFeelId,\n        accentLevels: nextAccentLevels,\n      }),\n    })\n    this.persistPrefs(\n      this.snapshot.bpm,\n      nextMeter,\n      nextSubdivision,\n      nextFeelId,\n      this.snapshot.accentLevels,\n      this.snapshot.soundId,\n      defaults.pulseModeId,\n    )\n    if (import.meta.env.DEV) {\n      console.log(`[MetronomeTab] timeSignature=${nextMeter}`)\n    }\n    this.pushNativeTimingUpdate()\n  }\n\n  setPulseMode = (nextPulseModeId: string): void => {\n    if (!meterHasPulseModeChoice(this.snapshot.meter)) return\n    const defaults = getMeterDefaults(this.snapshot.meter, nextPulseModeId)\n    const nextAccentLevels = getAccentLevelsForMeter(\n      this.snapshot.meter,\n      defaults.feelId,\n      nextPulseModeId,\n    )\n    this.tickCounter = 0\n    this.patchState({\n      pulseModeId: nextPulseModeId,\n      subdivision: defaults.subdivision,\n      feelId: defaults.feelId,\n      accentLevels: nextAccentLevels,\n      beatIndex: 0,\n      subTickIndex: 0,\n      ...this.enrichPulseFields({\n        pulseModeId: nextPulseModeId,\n        feelId: defaults.feelId,\n        accentLevels: nextAccentLevels,\n      }),\n    })\n    this.persistPrefs(\n      this.snapshot.bpm,\n      this.snapshot.meter,\n      defaults.subdivision,\n      defaults.feelId,\n      this.snapshot.accentLevels,\n      this.snapshot.soundId,\n      nextPulseModeId,\n    )\n    this.pushNativeTimingUpdate()\n  }\n\n  setFeel = (nextFeelId: string): void => {\n    if (!hasFeelOptions(this.snapshot.meter, this.snapshot.pulseModeId)) return\n    const nextAccentLevels = getAccentLevelsForMeter(\n      this.snapshot.meter,\n      nextFeelId,\n      this.snapshot.pulseModeId,\n    )\n    this.tickCounter = 0\n    this.patchState({\n      feelId: nextFeelId,\n      accentLevels: nextAccentLevels,\n      beatIndex: 0,\n      subTickIndex: 0,\n      ...this.enrichPulseFields({ feelId: nextFeelId, accentLevels: nextAccentLevels }),\n    })\n    this.persistPrefs(\n      this.snapshot.bpm,\n      this.snapshot.meter,\n      this.snapshot.subdivision,\n      nextFeelId,\n      nextAccentLevels,\n    )\n    if (import.meta.env.DEV) {\n      console.log(`[MetronomeTab] feel=${nextFeelId}`)\n    }\n    this.pushNativeTimingUpdate()\n  }\n\n  setSubdivision = (nextSubdivision: MetronomeSubdivision): void => {\n    this.tickCounter = 0\n    this.patchState({ subdivision: nextSubdivision, beatIndex: 0, subTickIndex: 0 })\n    this.persistPrefs(\n      this.snapshot.bpm,\n      this.snapshot.meter,\n      nextSubdivision,\n      this.snapshot.feelId,\n      this.snapshot.accentLevels,\n    )\n    if (import.meta.env.DEV) {\n      console.log(`[MetronomeTab] subdivision=${nextSubdivision}`)\n    }\n    this.pushNativeTimingUpdate()\n  }\n\n  setAccentLevels = (nextAccentLevels: MetronomeAccentLevel[]): void => {\n    const levels = normalizeAccentLevels(\n      this.snapshot.meter,\n      nextAccentLevels,\n      this.snapshot.feelId,\n      this.snapshot.pulseModeId,\n    )\n    this.patchState({\n      accentLevels: levels,\n      ...this.enrichPulseFields({ accentLevels: levels }),\n    })\n    this.persistPrefs(\n      this.snapshot.bpm,\n      this.snapshot.meter,\n      this.snapshot.subdivision,\n      this.snapshot.feelId,\n      levels,\n    )\n    this.pushNativeTimingUpdate()\n  }\n\n  /** @deprecated Use setAccentLevels */\n  setAccentPattern = (nextAccentPattern: boolean[]): void => {\n    const levels = normalizeAccentLevels(\n      this.snapshot.meter,\n      nextAccentPattern.map((accented, index) => {\n        if (!accented) return 'weak'\n        return index === 0 ? 'strong' : 'medium'\n      }),\n      this.snapshot.feelId,\n      this.snapshot.pulseModeId,\n    )\n    this.setAccentLevels(levels)\n  }\n\n  toggleBeatAccent = (beatIndex: number): void => {\n    const beats = this.snapshot.pulseCount\n    if (beatIndex < 0 || beatIndex >= beats) return\n    const levels = normalizeAccentLevels(\n      this.snapshot.meter,\n      [...this.snapshot.accentLevels],\n      this.snapshot.feelId,\n      this.snapshot.pulseModeId,\n    )\n    const current = levels[beatIndex] ?? 'weak'\n    levels[beatIndex] = cycleAccentLevel(current)\n    this.setAccentLevels(levels)\n  }\n\n  /** Legacy control for audio stage / camera widget \u2014 toggles accent on beat 1 only. */\n  setAccentFirstBeat = (nextAccentFirstBeat: boolean): void => {\n    const levels = normalizeAccentLevels(\n      this.snapshot.meter,\n      [...this.snapshot.accentLevels],\n      this.snapshot.feelId,\n      this.snapshot.pulseModeId,\n    )\n    if (levels.length > 0) {\n      levels[0] = nextAccentFirstBeat ? 'strong' : 'weak'\n    }\n    this.setAccentLevels(levels)\n  }\n\n  setSoundId = (nextSoundId: string): void => {\n    this.patchState({ soundId: nextSoundId })\n    this.persistPrefs(\n      this.snapshot.bpm,\n      this.snapshot.meter,\n      this.snapshot.subdivision,\n      this.snapshot.feelId,\n      this.snapshot.accentLevels,\n      nextSoundId,\n    )\n    this.pushNativeTimingUpdate()\n  }\n\n  /** Apply section settings during timeline playback without overwriting saved metronome prefs. */\n  applySectionConfig = (\n    config: {\n      bpm: number\n      meter: MetronomeMeter\n      subdivision: MetronomeSubdivision\n      feelId?: string\n      pulseModeId?: string\n      accentLevels: MetronomeAccentLevel[]\n      soundId?: string\n    },\n    options?: { resetBeat?: boolean },\n  ): void => {\n    const nextBpm = clampBpm(config.bpm)\n    const pulseModeId = config.pulseModeId ?? getMeterDefaults(config.meter).pulseModeId\n    const levels = normalizeAccentLevels(\n      config.meter,\n      config.accentLevels,\n      config.feelId,\n      pulseModeId,\n    )\n    const resetBeat = options?.resetBeat !== false\n    if (resetBeat) this.tickCounter = 0\n    this.patchState({\n      bpm: nextBpm,\n      meter: config.meter,\n      subdivision: config.subdivision,\n      feelId: config.feelId,\n      pulseModeId,\n      accentLevels: levels,\n      ...(resetBeat ? { beatIndex: 0, subTickIndex: 0 } : {}),\n      ...(config.soundId ? { soundId: config.soundId } : {}),\n      ...this.enrichPulseFields({\n        meter: config.meter,\n        pulseModeId,\n        feelId: config.feelId,\n        accentLevels: levels,\n      }),\n    })\n    this.pushNativeTimingUpdate()\n  }\n\n  private clearSchedulerTimer(): void {\n    if (this.schedulerTimer !== null) {\n      window.clearTimeout(this.schedulerTimer)\n      this.schedulerTimer = null\n    }\n  }\n\n  private releaseAudioGraph(): void {\n    try {\n      this.masterGain?.disconnect()\n    } catch {\n      /* already disconnected */\n    }\n    this.masterGain = null\n    this.audioCtx = null\n  }\n\n  private ensureMasterGain(ctx: AudioContext): GainNode {\n    let master = this.masterGain\n    if (!master || master.context !== ctx) {\n      master = ctx.createGain()\n      master.gain.value = metronomeSpeakerGain(this.shouldMuteOutput()) * this.outputGainMultiplier\n      master.connect(ctx.destination)\n      this.masterGain = master\n    } else {\n      master.gain.setValueAtTime(\n        metronomeSpeakerGain(this.shouldMuteOutput()) * this.outputGainMultiplier,\n        ctx.currentTime,\n      )\n    }\n    return master\n  }\n\n  private async prepareAudioContextForStart(): Promise<AudioContext | null> {\n    const wasReleased = this.audioCtx === null\n\n    await resumePlaybackAudioContext()\n\n    let ctx = primePlaybackAudioContextSync()\n    if (ctx.state === 'closed') {\n      ctx = primePlaybackAudioContextSync()\n    }\n\n    this.masterGain = null\n    this.audioCtx = ctx\n    this.attachPlaybackInterruptWatch()\n\n    if (wasReleased) {\n      this.debugLog('audio context recreated')\n    }\n\n    // iOS WKWebView can report 'interrupted' (non-standard) after a native\n    // capture session reconfigures the audio session \u2014 treat any non-running\n    // state as resumable, not just 'suspended'.\n    let audioState: AudioContextState = ctx.state\n    if (audioState !== 'running') {\n      for (let attempt = 0; attempt < 4; attempt++) {\n        try {\n          await ctx.resume()\n        } catch {\n          /* iOS may block until audio session is ready */\n        }\n        audioState = ctx.state\n        if (audioState === 'running') break\n        await new Promise((resolve) => window.setTimeout(resolve, 50 * (attempt + 1)))\n      }\n\n      if (audioState !== 'running') {\n        this.debugLog(`audio context resume blocked (state=${audioState})`)\n        return null\n      }\n\n      this.debugLog('audio context resumed')\n    }\n\n    return ctx\n  }\n\n  private runSchedulerLoop(): void {\n    if (!this.snapshot.playing) return\n\n    if (this.schedulerTimer !== null) {\n      this.debugLog('prevented duplicate scheduler')\n      this.clearSchedulerTimer()\n    }\n\n    const sessionId = this.schedulerSession\n\n    const tick = () => {\n      if (!this.snapshot.playing || sessionId !== this.schedulerSession) return\n\n      const activeCtx = this.audioCtx\n      if (!activeCtx || activeCtx.state === 'closed') {\n        this.hardStop()\n        return\n      }\n\n      if (activeCtx.state !== 'running') {\n        this.requestWebAudioResume(activeCtx)\n        this.schedulerTimer = window.setTimeout(tick, LOOKAHEAD_MS)\n        return\n      }\n\n      const meter = this.snapshot.meter\n      const subdivision = this.snapshot.subdivision\n      const pulseCount = this.snapshot.pulseCount\n      const barTicks = ticksPerBar(meter, subdivision, pulseCount)\n      const secondsPerTick = secondsPerSchedulerTick(meter, this.snapshot.bpm, subdivision, pulseCount)\n      const outputNode = this.ensureMasterGain(activeCtx)\n      const muted = this.shouldMuteOutput()\n      const sound = this.snapshot.soundId\n\n      // A throttled tab or interrupted Web Audio context can leave the next\n      // scheduled tick far behind the audio clock. Catching up one tick at a\n      // time would create every missed oscillator at once and can exhaust\n      // WebKit after a long interruption. Advance the musical phase directly\n      // to the first current tick instead.\n      if (this.nextBeatTime < activeCtx.currentTime - SCHEDULE_AHEAD_SEC) {\n        const skippedTicks = Math.max(\n          1,\n          Math.floor((activeCtx.currentTime - this.nextBeatTime) / secondsPerTick) + 1,\n        )\n        this.nextBeatTime += skippedTicks * secondsPerTick\n        this.tickCounter += skippedTicks\n        this.debugLog(`scheduler skipped ${skippedTicks} stale ticks`)\n      }\n\n      while (this.nextBeatTime < activeCtx.currentTime + SCHEDULE_AHEAD_SEC) {\n        const tickInBar = this.tickCounter % barTicks\n        const beatTime = this.nextBeatTime\n        const tier = resolveClickTierWithAccents(\n          meter,\n          tickInBar,\n          subdivision,\n          this.snapshot.accentLevels,\n          pulseCount,\n        )\n        if (tier) {\n          scheduleMetronomeClick(activeCtx, beatTime, tier, outputNode, muted, sound)\n        }\n\n        if (beatTime - activeCtx.currentTime <= SCHEDULE_AHEAD_SEC) {\n          const uiTick = resolveUiTick(meter, tickInBar, subdivision, pulseCount)\n          const uiBeat = uiTick.beatIndex\n          const uiSubTick = uiTick.subTickIndex\n          const uiTickAudible = Boolean(tier) && !muted\n          // React 18 batches synchronous state updates, so if several ticks fall in the\n          // same lookahead pass (startup backlog, or a delayed poll catching up), patching\n          // state for each one inline would collapse into a single render of the last tick\n          // only \u2014 silently dropping earlier ticks, most visibly the main beat (subTick 0).\n          // Scheduling each tick's UI update on its own timer, matched to its audio time,\n          // keeps every tick in its own render pass and lines the flash up with the click.\n          const uiDelayMs = Math.max(0, (beatTime - activeCtx.currentTime) * 1000)\n          window.setTimeout(() => {\n            if (!this.snapshot.playing || sessionId !== this.schedulerSession) return\n            this.emitTick({\n              beatIndex: uiBeat,\n              subTickIndex: uiSubTick,\n              audible: uiTickAudible,\n            })\n            if (uiSubTick === 0) this.emitPulse(uiBeat)\n            this.patchState({\n              beatIndex: uiBeat,\n              subTickIndex: uiSubTick,\n              beatPulseId: this.snapshot.beatPulseId + 1,\n            })\n            this.debugLog(`beat=${uiBeat + 1} subTick=${uiSubTick}`)\n          }, uiDelayMs)\n        }\n\n        this.nextBeatTime += secondsPerTick\n        this.tickCounter += 1\n        if (this.tickCounter > 0 && this.tickCounter % barTicks === 0) {\n          this.emitBar()\n        }\n      }\n\n      this.schedulerTimer = window.setTimeout(tick, LOOKAHEAD_MS)\n    }\n\n    const ctx = this.audioCtx\n    if (!ctx) return\n\n    if (this.nextBeatTime <= 0 || this.nextBeatTime < ctx.currentTime) {\n      this.nextBeatTime = ctx.currentTime + START_LEAD_SEC\n    }\n\n    tick()\n  }\n\n  private isSchedulerHealthy(): boolean {\n    if (this.useNativeAudio) {\n      return this.snapshot.playing\n    }\n    return (\n      this.schedulerTimer !== null &&\n      this.audioCtx !== null &&\n      this.audioCtx.state === 'running'\n    )\n  }\n\n  private sanityReset(): void {\n    this.debugLog('sanity reset')\n    this.controlGeneration += 1\n    this.schedulerSession += 1\n    this.clearSchedulerTimer()\n    if (this.useNativeAudio) {\n      void this.enqueueNativeControl(nativeMetronomeStop)\n    }\n    this.patchState({ playing: false })\n  }\n\n  reconcileAfterModeSwitch(targetMode: 'video' | 'audio' = 'video'): void {\n    if (!this.snapshot.playing) return\n    void this.recoverAfterModeSwitch(targetMode)\n  }\n\n  /** A sheet is not an audio interruption. Recover only when lifecycle state\n   * or the web scheduler reports a problem; reasserting the native speaker\n   * route on every Settings close can interrupt the live camera session. */\n  reconcileAfterSurfaceTransition(_targetMode: 'video' | 'audio' = 'video'): void {\n    this.reconcileAfterInterrupt()\n  }\n\n  private async recoverAfterModeSwitch(targetMode: 'video' | 'audio'): Promise<void> {\n    if (!this.snapshot.playing) return\n\n    // A single mode switch fires this from the React effect AND from three\n    // settle timers. Without a generation guard those passes interleave:\n    // `start()` short-circuits on `startInFlight`, the losing pass reads that\n    // as a failed attempt and calls `clearSchedulerTimer()` on the scheduler\n    // the winning pass just built, and whichever pass exhausts its retries\n    // last flips `playing:false` \u2014 the metronome switching itself off on the\n    // way back into Tools. Only the newest pass may act.\n    const generation = ++this.modeSwitchRecoveryGeneration\n    const superseded = () => generation !== this.modeSwitchRecoveryGeneration\n\n    const enteringCamera = targetMode === 'video'\n\n    if (enteringCamera) {\n      // Releasing stereo during bridge acquire calls enableRecordingRoute and\n      // kills the capture session (black preview). Wait for live preview, then\n      // only refresh the native metronome engine \u2014 no route release cycle.\n      for (let attempt = 0; attempt < 12; attempt++) {\n        if (!this.snapshot.playing || superseded()) return\n        if (attempt > 0) {\n          await new Promise((resolve) => window.setTimeout(resolve, 150 * attempt))\n          if (superseded()) return\n        }\n        try {\n          const snapshot = await BestTakeAudioPlugin.getCameraSessionState()\n          if (snapshot.previewActive !== true && attempt < 11) continue\n          await nativeMetronomePrepare()\n          if (!this.isSchedulerHealthy()) {\n            const started = await this.start({ recovered: true, fromStale: true })\n            if (started && this.isSchedulerHealthy()) return\n            this.clearSchedulerTimer()\n            continue\n          }\n          this.applyMasterGain()\n          return\n        } catch {\n          /* retry */\n        }\n      }\n      this.debugLog('camera mode-switch recovery failed')\n      return\n    }\n\n    await this.reassertNativeSpeakerRoute()\n    if (superseded()) return\n\n    if (Capacitor.isNativePlatform()) {\n      try {\n        const { reassertPlaybackRouteForCountIn } = await import('../utils/playbackRouteCoordinator')\n        await reassertPlaybackRouteForCountIn()\n      } catch {\n        /* route may be blocked briefly while camera hands off */\n      }\n      if (superseded()) return\n    }\n\n    if (this.isSchedulerHealthy()) {\n      this.applyMasterGain()\n      return\n    }\n\n    this.schedulerSession += 1\n    this.clearSchedulerTimer()\n\n    for (let attempt = 0; attempt < 8; attempt++) {\n      if (!this.snapshot.playing || superseded()) return\n\n      if (attempt > 0) {\n        await new Promise((resolve) => window.setTimeout(resolve, 120 * attempt))\n        if (superseded()) return\n        await resumePlaybackAudioContext()\n        if (Capacitor.isNativePlatform()) {\n          try {\n            const { reassertPlaybackRouteForCountIn } = await import('../utils/playbackRouteCoordinator')\n            await reassertPlaybackRouteForCountIn()\n          } catch {\n            /* retry */\n          }\n        }\n        if (superseded()) return\n      }\n\n      const started = await this.start({ recovered: true, fromStale: true })\n      if (superseded()) return\n      if (started && this.isSchedulerHealthy()) {\n        this.applyMasterGain()\n        return\n      }\n      this.clearSchedulerTimer()\n    }\n\n    if (superseded()) return\n    this.debugLog('mode-switch recovery failed')\n    // The metronome stays on. The user turned it on; a route handoff between\n    // camera and Tools is not their instruction to turn it off. Web Audio gets\n    // one more recovery pass here; on the native engine `playing` simply stays\n    // set, so the next reconcile \u2014 or a tap on the button, which sanity-resets\n    // an unhealthy scheduler and restarts \u2014 brings the click back.\n    this.reconcileAfterInterrupt()\n  }\n\n  /**\n   * Reset stale scheduler / foreground-recovery state and ensure the Web Audio\n   * graph is running before a multitrack count-in (especially first take, where\n   * reference playback does not wake the context).\n   */\n  prepareForCountIn = async (): Promise<boolean> => {\n    this.resumeOnForeground = false\n    this.recoveringForeground = false\n    if (this.foregroundTimer !== null) {\n      window.clearTimeout(this.foregroundTimer)\n      this.foregroundTimer = null\n    }\n    this.sanityReset()\n    if (this.useNativeAudio) {\n      await this.ensureNativeSpeakerRoute()\n      await this.enqueueNativeControl(async () => {})\n      const [ctx, prepared] = await Promise.all([\n        this.prepareAudioContextForStart(),\n        nativeMetronomePrepare(),\n      ])\n      return Boolean(ctx && prepared)\n    }\n    const ctx = await this.prepareAudioContextForStart()\n    return !!(ctx && ctx.state === 'running')\n  }\n\n  private hardStop(options?: { background?: boolean }): void {\n    if (this.snapshot.playing && !options?.background) {\n      this.debugLog('stop')\n    }\n    this.controlGeneration += 1\n    if (this.useNativeAudio) {\n      void this.enqueueNativeControl(nativeMetronomeStop)\n    }\n    this.schedulerSession += 1\n    this.clearSchedulerTimer()\n    this.patchState({ playing: false })\n    void this.releaseNativeSpeakerRoute().catch(() => {})\n    if (options?.background) {\n      this.releaseAudioGraph()\n    }\n  }\n\n  stop = (): void => {\n    this.resumeOnForeground = false\n    this.resumeClickWanted = false\n    this.clickResumeUntil = 0\n    this.clickResumeGeneration += 1\n    this.hardStop()\n  }\n\n  start = async (options?: {\n    recovered?: boolean\n    fromStale?: boolean\n    /** Extra lead before the first click (e.g. wait for HTMLMediaElement to reach the speaker). */\n    firstBeatDelaySec?: number\n  }): Promise<boolean> => {\n    if (typeof window === 'undefined') return false\n    if (this.startInFlight) return false\n\n    this.startInFlight = true\n    let startGeneration = 0\n    let started = false\n\n    try {\n      if (this.snapshot.playing && !this.isSchedulerHealthy() && !options?.fromStale) {\n        this.debugLog('start recovered from stale state')\n        this.sanityReset()\n      }\n      startGeneration = ++this.controlGeneration\n\n      this.clearSchedulerTimer()\n\n      try {\n        await this.ensureNativeSpeakerRoute()\n      } catch {\n        this.debugLog('speaker route preparation deferred to native start')\n      }\n      if (startGeneration !== this.controlGeneration || this.isBackgrounded) return false\n\n      if (this.useNativeAudio) {\n        this.attachNativeListeners()\n        const leadSec = Math.max(START_LEAD_SEC, options?.firstBeatDelaySec ?? START_LEAD_SEC)\n        const anchorCtx =\n          this.audioCtx && this.audioCtx.state === 'running' ? this.audioCtx : null\n        const result = await this.enqueueNativeControl(() =>\n          nativeMetronomeStart({\n            ...this.buildNativeTimingPayload(),\n            muted: this.shouldMuteOutput(),\n            leadSec,\n          }),\n        )\n        if (startGeneration !== this.controlGeneration) {\n          await this.enqueueNativeControl(nativeMetronomeStop)\n          return false\n        }\n        if (result?.playing) {\n          this.lastStartInfo = {\n            firstClickCtxTime: anchorCtx ? anchorCtx.currentTime + leadSec : 0,\n            firstClickPerfMs: result.firstClickPerfMs,\n          }\n          this.patchState({ playing: true, beatIndex: 0, subTickIndex: 0, beatPulseId: 0 })\n          this.debugLog(options?.recovered ? 'start native (recovered)' : 'start native')\n          started = true\n          return true\n        }\n        this.debugLog('native metronome unavailable \u2014 rebuild iOS app after cap:sync; using Web Audio fallback')\n      }\n\n      const ctx = await this.prepareAudioContextForStart()\n      if (startGeneration !== this.controlGeneration || this.isBackgrounded) return false\n      if (!ctx || ctx.state === 'closed') {\n        this.schedulerSession += 1\n        this.clearSchedulerTimer()\n        this.patchState({ playing: false })\n        return false\n      }\n\n      this.tickCounter = 0\n      const leadSec = Math.max(START_LEAD_SEC, options?.firstBeatDelaySec ?? START_LEAD_SEC)\n      this.nextBeatTime = ctx.currentTime + leadSec\n      // Capture the sample-accurate first-click moment on both clocks BEFORE the\n      // scheduler runs \u2014 this is the anchor multitrack timing derives from.\n      this.lastStartInfo = {\n        firstClickCtxTime: this.nextBeatTime,\n        firstClickPerfMs: performance.now() + leadSec * 1000,\n      }\n      this.schedulerSession += 1\n      this.patchState({ playing: true, beatIndex: 0, subTickIndex: 0, beatPulseId: 0 })\n      this.debugLog(options?.recovered ? 'start (recovered)' : 'start')\n      this.runSchedulerLoop()\n      started = true\n      return true\n    } finally {\n      if (!started) {\n        void this.releaseNativeSpeakerRoute().catch(() => {})\n      }\n      this.startInFlight = false\n    }\n  }\n\n  togglePlay = (): void => {\n    if (this.snapshot.playing) {\n      if (!this.isSchedulerHealthy()) {\n        this.resumeOnForeground = false\n        this.sanityReset()\n        void this.start()\n      } else {\n        this.stop()\n      }\n      return\n    }\n    this.resumeOnForeground = false\n    void this.start()\n  }\n}\n\nexport const sharedMetronomeEngine = new SharedMetronomeEngine()\n"
import assert from 'node:assert/strict'
import { build } from 'esbuild'

const listeners = new Map()
const nativeListeners = new Map()
const storage = new Map()
globalThis.localStorage = { getItem: key => storage.get(key) ?? null, setItem: (key, value) => storage.set(key, value) }
globalThis.window = {
  addEventListener(name, fn) { const list = listeners.get(name) ?? []; list.push(fn); listeners.set(name, list) },
  setTimeout, clearTimeout, setInterval, clearInterval,
}
globalThis.document = { visibilityState: 'visible', addEventListener: window.addEventListener }
const native = { playing: false, starts: 0, stops: 0, muted: false, gate: null, statusGate: null }
globalThis.__backgroundNative = native
globalThis.__backgroundListeners = nativeListeners
const noop = 'async () => {}'
const mocks = {
  '@capacitor/core': "export const Capacitor = { isNativePlatform: () => true, getPlatform: () => 'ios' }",
  '@capacitor/app': "export const App = { addListener: async (name, fn) => { globalThis.__backgroundListeners.set(name, fn); return { remove() {} } } }",
  nativeMetronome: `const n = globalThis.__backgroundNative;
    export const isNativeIosMetronome = () => true;
    export const nativeMetronomeStart = async payload => { n.startPayload = structuredClone(payload); n.timing = structuredClone(payload); n.starts++; const ok = !n.failStart; n.playing = ok; if(n.gate) await n.gate; return ok ? {playing:true,firstClickPerfMs:0} : null };
    export const nativeMetronomeStop = async () => { n.stops++; n.playing = false };
    export const nativeMetronomeIsPlaying = async () => { const playing = n.statusUnknown ? null : n.playing; if(n.statusGate) await n.statusGate; return playing };
    export const nativeMetronomeSetMuted = async muted => { n.muted = muted };
    export const nativeMetronomePrepare = async () => true;
    export const nativeMetronomeUpdate = async payload => { n.updates = (n.updates ?? 0) + 1; n.timing = structuredClone(payload) };
    export const nativeMetronomeAddPulseListener = ${noop};
    export const nativeMetronomeAddBarListener = ${noop};
    export const nativeMetronomeAddStateListener = async fn => { n.onState = fn };`,
  audioSessionRoute: 'export default {}',
  headphoneOutput: 'export const isHeadphoneOutputActive = () => false',
  stereoPlaybackRoute: `export const engageStereoPlaybackAsync = ${noop}; export const releaseStereoPlayback = ${noop}`,
  playbackRouteCoordinator: `export const isPlaybackRouteHoldActive = () => true; export const preparePlaybackRoute = ${noop}; export const reassertPlaybackRouteForCountIn = async () => { if(globalThis.__backgroundNative.routeGate) await globalThis.__backgroundNative.routeGate }`,
  playbackAudioContext: 'export const primePlaybackAudioContextSync = () => null; export const resumePlaybackAudioContext = async () => { if(globalThis.__backgroundNative.failFallback) throw Error("Test fallback unavailable") }',
}
const result = await build({ entryPoints: ['src/metronome/sharedMetronomeEngine.ts'], bundle: true, write: false, platform: 'node', format: 'esm', define: {'import.meta.env.DEV': 'false'}, plugins: [{ name: 'native-boundaries', setup(b) {
  b.onLoad({filter:/sharedMetronomeEngine\.ts$/},()=>({contents:baselineSource,loader:'ts',resolveDir:process.cwd()+'/src/metronome'}))
  b.onResolve({ filter: /.*/ }, args => { const key = mocks[args.path] ? args.path : args.path.split('/').at(-1); if(mocks[key]) return {path:key, namespace:'mock'} })
  b.onLoad({ filter: /.*/, namespace: 'mock' }, args => ({contents: mocks[args.path]}))
} }] })
const {sharedMetronomeEngine: engine} = await import(`data:text/javascript;base64,${Buffer.from(result.outputFiles[0].text).toString('base64')}`)
const flush = () => new Promise(resolve => setImmediate(resolve))
// Production shared engine; fixtures replace only browser/native audio boundaries.
const deferred = () => { let resolve; const promise = new Promise(r => { resolve = r }); return {promise, resolve} }
const settleStop = async () => { engine.stop(); await flush(); await flush() }
const updates = () => native.updates ?? 0
const base = () => { engine.setMeter('4/4'); engine.setSubdivision('off'); engine.setBpm(80); engine.setSoundId('classic') }
base()
// A normal Start needs no additional timing update.
const firstUpdates = updates()
assert.equal(await engine.start(), true)
assert.equal(updates(), firstUpdates)
assert.equal(native.timing.secondsPerTick, .75)
await settleStop()

// Start has submitted its old payload; every control remains available while awaiting the reply.
base()
let gate = deferred(); native.gate = gate.promise
let start = engine.start(); await flush()
assert.equal(engine.getSnapshot().playing, false)
assert.equal(native.startPayload.secondsPerTick, .75)
const beforeEdits = updates()
engine.setBpm(160)
engine.setMeter('3/4')
engine.setSubdivision('16ths')
engine.setAccentLevels(['weak', 'medium', 'strong'])
engine.setSoundId('woodblock')
assert.equal(updates(), beforeEdits, 'Timing edits defer while the Start acknowledgement is pending')
gate.resolve(); assert.equal(await start, true); native.gate = null; await flush()
assert.equal(updates(), beforeEdits + 1, 'Successful Start reconciles the latest settings once')
assert.equal(native.timing.secondsPerTick, 60 / 160 / 4)
assert.equal(native.timing.ticksPerBar, 12)
assert.equal(native.timing.pulseTicks, 4)
assert.equal(native.timing.soundId, 'woodblock')
assert.equal(native.timing.tierPattern[0], 'beat')
assert.equal(native.timing.tierPattern[4], 'macro')
assert.equal(native.timing.tierPattern[8], 'downbeat')
assert.deepEqual(engine.getSnapshot().accentLevels, ['weak', 'medium', 'strong'])
await settleStop()

// Changes during route preparation are captured by Start itself, not replayed afterward.
base(); gate = deferred(); native.routeGate = gate.promise
start = engine.start(); await flush()
engine.setBpm(144); engine.setSoundId('soft')
const beforeRouteAck = updates()
gate.resolve(); assert.equal(await start, true); native.routeGate = null; await flush()
assert.equal(native.startPayload.secondsPerTick, 60 / 144)
assert.equal(native.startPayload.soundId, 'soft')
assert.equal(updates(), beforeRouteAck)
await settleStop()

// A late old acknowledgement after Stop cannot reconcile timing or undo Stop.
base(); gate = deferred(); native.gate = gate.promise
start = engine.start(); await flush()
engine.setBpm(200); engine.setMeter('6/8'); engine.setPulseMode('simple')
engine.stop()
assert.equal(await engine.start(), false, 'A newer Start waits until the pending native control settles')
const beforeStaleAck = updates()
gate.resolve(); assert.equal(await start, false); native.gate = null; await flush()
assert.equal(updates(), beforeStaleAck)
assert.equal(engine.getSnapshot().playing, false)
assert.equal(native.playing, false)
assert.equal(await engine.start(), true, 'A subsequent Start accepts the latest settings after the old reply settles')
assert.equal(native.startPayload.secondsPerTick, .3 / 3)
assert.equal(native.startPayload.ticksPerBar, 6)
assert.equal(updates(), beforeStaleAck, 'Old revisions cannot leak into the new Start')
await settleStop()

// A rejected native reply plus unavailable fallback cannot emit reconciliation; retry stays usable.
base(); gate = deferred(); native.gate = gate.promise; native.failStart = true; native.failFallback = true
start = engine.start(); await flush()
engine.setBpm(150); engine.setSoundId('electronic')
const beforeFailure = updates()
gate.resolve(); await assert.rejects(start, /Test fallback unavailable/)
native.gate = null; native.failStart = false; native.failFallback = false; await flush()
assert.equal(updates(), beforeFailure)
assert.equal(engine.getSnapshot().playing, false)
assert.equal(await engine.start(), true)
assert.equal(native.startPayload.secondsPerTick, .4)
assert.equal(native.startPayload.soundId, 'electronic')
assert.equal(updates(), beforeFailure)
await settleStop()

// A synchronous subscriber Stop when success is published also invalidates reconciliation.
base(); gate = deferred(); native.gate = gate.promise
start = engine.start(); await flush(); engine.setBpm(180)
const beforeSubscriberStop = updates()
const unsubscribe = engine.subscribe(() => { if(engine.getSnapshot().playing) engine.stop() })
gate.resolve(); await start; native.gate = null; unsubscribe(); await flush()
assert.equal(engine.getSnapshot().playing, false)
assert.equal(native.playing, false)
assert.equal(updates(), beforeSubscriberStop)
console.log('PASS: native Start uses latest pending BPM/meter/subdivision/accents/sound; pre-dispatch changes, delayed reply after Stop/new Start, failure/retry and subscriber Stop respect control generations.')
